    local function VM_I1lO(d, k, m)
        local R_Oll0OO = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_Oll0OO, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_Oll0OO)
    end

    -- Execution Guard
    local F_0Il0OI0 = loadstring(VM_I1lO(B_111I1O, 75, 5))
    if F_0Il0OI0 then
        F_0Il0OI0(...)
    end
end)(...)
